P = [
 dict(pmid='43025105', doi='10.1016/j.marpolbul.2026.120542', journal='Mar Pollut Bull', title='Ship emission accounting and air quality impact in Tianjin Port: Application of bottom-up method and AERMOD model.', short='Dalian Maritime Tianjin Port AIS bottom-up ship emission inventory AERMOD PM2.5 216.73 Mg May-July 2021', design='Health impact model', pm='Ship PM10 and PM2.5 emissions (AIS bottom-up) and AERMOD-dispersed ambient contributions', geo='China (Tianjin)', endpoint='Emissions by vessel type and mode; contribution to ambient pollutants at nearest station', tier='C', basis='Model (CTM / LUR / ML)', affil='Dalian Maritime University, China; Dalian Maritime University, China', n='AIS-based bottom-up inventory of ship emissions at Tianjin Port for May-July 2021, dispersed with AERMOD. Ships emitted 237.97 Mg PM10 and 216.73 Mg PM2.5 alongside 1,663.85 Mg SO2 and 8,123.43 Mg NOx; conventional ships produced 40.70% of total emissions and berthing more than 32% of SO2 and 43% of NOx. At the monitoring station nearest the port ships contributed 79.13% of ambient SO2 and 58.22% of NOx but under 10% of particulate matter. Three summer months only, no model evaluation statistics in the abstract, and AERMOD omits secondary particle formation, which is how ship SO2 and NOx become PM. Relevance: indirect - port fenceline PM sensors will miss the ship signal in primary mass; SO2/NOx co-sensing is the better tracer.', sub=corpus.BURD),
 dict(pmid='43029722', doi='10.3390/s26216924', journal='Sensors (Basel)', title='Source-Space Coverage Outweighs Receptor Placement in Sparse Urban Emission Inversion Under Matched and Moderately Misspecified Transport: A Mixed Point-Road Simulation Benchmark.', short='Chengdu 30 synthetic cities emission inversion sensor placement vs source coverage calibration error truth-free residual', design='Methodological simulation with applied case study', pm='Pollutant-agnostic receptor network inversion; applied to seven Chengdu NO2 stations', geo='China (Chengdu; synthetic cities)', endpoint='Normalised source-rate error by design decision; residual AUC for model error', tier='C', basis='Model (CTM / LUR / ML)', affil='Chengdu Vocational & Technical College of Industry, China; Dalian University of Technology, China', n='Benchmark over 30 synthetic cities placing five network design decisions on one error scale for emission-rate inversion from concentration-mapping monitors. Under matched transport, covering traffic in the source dictionary changed normalised source error by 0.74 and dictionary fidelity and sensor calibration by about 0.68 each, versus 0.13-0.15 across placement criteria; under a mismatched dispersion generator the coverage effect fell to the size of placement. Unmodelled mixing height was among the commonest errors (0.41-0.53); a truth-free residual flagged severe model error (AUC 0.89-0.95). Applied to seven Chengdu NO2 stations, estimates were withheld for poor skill. Synthetic only; no PM application. Relevance: direct for network design - sensor calibration error outweighs siting choice by about fivefold for source inversion.', sub=corpus.SENS),
 dict(pmid='', doi='10.64898/2026.11.11.26367854', journal='medRxiv', title='High-resolution spatiotemporal estimates of total and wildfire PM 2.5 in the contiguous United States, 2018-2024: Implications for population exposure and mortality burden', short='UW medRxiv CONUS 1-km daily total and wildfire PM2.5 2018-2024 ML smoke density attributable deaths', design='Machine-learning model development', pm='Daily 1-km total and wildfire-specific PM2.5 from an ML model with precursors and smoke density', geo='USA (contiguous)', endpoint='Cross-validated R2; wildfire share of PM2.5 and of attributable deaths', tier='A', basis='Model (CTM / LUR / ML)', affil='University of Washington, USA; University of Washington, USA', n='Preprint. ML framework estimating daily 1-km total and wildfire-attributable PM2.5 over the contiguous US for 2018-2024 from public data, including chemical precursors and smoke density. Cross-validated R2 was 0.72 daily and 0.89 annual. Wildfire smoke supplied about 35% of PM2.5 along the west coast in 2020 and over 25% in the eastern US in 2023; wildfire PM2.5 accounted for 20% of PM2.5-attributable deaths on the west coast in 2020 (30 times 2019) and 24% in the north-east in 2023 (14 times 2019). Not peer reviewed; the abstract gives no error on the wildfire component itself, the hardest part to validate, nor the concentration-response function used. Relevance: direct - a candidate exposure surface whose daily skill (R2 0.72) leaves room for PurpleAir fusion in smoke events.', sub=corpus.EXPO),
 dict(pmid='', doi='10.21203/rs.3.rs-11403486/v1', journal='Research Square', title='Type I interferon signaling mediates silica-induced pulmonary B1 cell recruitment and autoimmunity', short='UCLouvain Research Square silica mice type I interferon Ifnar1 knockout B1 cells CXCL13 autoantibodies', design='Animal knockout experiment', pm='Crystalline silica particles instilled (dose not stated in abstract)', geo='Belgium (laboratory)', endpoint='IFN-I signature, autoantibodies, pulmonary B1-cell recruitment, CXCL13/CXCR5', tier='C', basis='Lab / research instrument', affil='UCLouvain, Belgium; UCLouvain, Belgium', n='Preprint. Silica exposure produced a sustained type I interferon signature in wild-type mice with raised lung and circulating anti-dsDNA, class-switched IgG, natural IgM and IgA; these humoral changes were markedly attenuated in Ifnar1-/- mice. Silica recruited innate-like B1 cells to the lung via the CXCL13/CXCR5 axis; without IFNAR, B1 cells accumulated in tracheobronchial nodes and spleen instead and CXCL13 induction was lost. Not peer reviewed; dose, route detail, group sizes and effect sizes are absent from the abstract, and crystalline silica is an occupational particle with toxicity specific to its surface chemistry, not ambient PM. Relevance: indirect - mechanistic link from particle lung injury to systemic autoimmunity; no measurement content.', sub=corpus.MECH),
]
